@use "functions/defaults" as *;
@use "mixins/form-control" as *;
@use "mixins/tokens" as *;
@use "calendar" as *;
@use "config" as *;
@use "time-picker" as *;

$date-picker-tokens: () !default;

// stylelint-disable scss/dollar-variable-default

// scss-docs-start date-picker-tokens
$date-picker-tokens: defaults(
  (
    --#{$prefix}date-picker-footer-padding: .5rem,
    --#{$prefix}date-picker-footer-border-width: 1px,
    --#{$prefix}date-picker-footer-border-color: var(--#{$prefix}border-color),
  ),
  $date-picker-tokens
);
// scss-docs-end date-picker-tokens

// stylelint-enable scss/dollar-variable-default
@layer components {

  .date-picker {
    position: relative;

    // A picker whose element is the frame carries the active state itself; one
    // that wraps a field component carries it on that field.
    &.show.form-control-group,
    &.show > .form-control-group {
      @include form-control-group-active();
    }
  }

  .date-picker-popup {
    @include tokens($date-picker-tokens);

    .date-picker-timepickers {
      display: flex;
      border-inline-start: var(--#{$prefix}date-picker-footer-border-width) solid var(--#{$prefix}date-picker-footer-border-color);
    }

    .time-picker-body {
      @include tokens($time-picker-tokens);
    }
  }

  .date-picker-body {
    display: flex;
  }

  .date-picker-ranges {
    display: flex;
    flex-direction: column;
    gap: .25rem;
    align-items: flex-start;
    padding: var(--#{$prefix}date-picker-footer-padding);
    border-inline-end: var(--#{$prefix}date-picker-footer-border-width) solid var(--#{$prefix}date-picker-footer-border-color);
  }

  .date-picker-calendars {
    display: flex;

    .date-picker-calendar:not(:last-child) .calendar-navigation-next {
      visibility: hidden;
    }

    .date-picker-calendar:not(:first-child) .calendar-navigation-prev {
      visibility: hidden;
    }
  }

  .date-picker-footer {
    display: flex;
    gap: .5rem;
    justify-content: flex-end;
    padding: var(--#{$prefix}date-picker-footer-padding);
    border-block-start: var(--#{$prefix}date-picker-footer-border-width) solid var(--#{$prefix}date-picker-footer-border-color);
  }

}
