@use "functions/defaults" as *;
@use "mixins/border-radius" as *;
@use "mixins/form-control" as *;
@use "mixins/tokens" as *;
@use "config" as *;

// Time Picker
$time-picker-tokens: () !default;

// stylelint-disable scss/dollar-variable-default

// scss-docs-start time-picker-tokens
$time-picker-tokens: defaults(
  (
    --#{$prefix}time-picker-body-padding: var(--#{$prefix}spacer-2),
    --#{$prefix}time-picker-footer-border-width: 1px,
    --#{$prefix}time-picker-footer-border-color: var(--#{$prefix}border-color),
    --#{$prefix}time-picker-footer-padding: .5rem,
    --#{$prefix}time-picker-roll-col-border-width: var(--#{$prefix}border-width),
    --#{$prefix}time-picker-roll-col-border-color: var(--#{$prefix}border-color),
    --#{$prefix}time-picker-roll-cell-width: 3rem,
    --#{$prefix}time-picker-roll-cell-height: 2rem,
    --#{$prefix}time-picker-roll-cell-hover-color: var(--#{$prefix}fg-body),
    --#{$prefix}time-picker-roll-cell-hover-bg: var(--#{$prefix}bg-1),
    --#{$prefix}time-picker-roll-cell-selected-color: var(--#{$prefix}primary-contrast),
    --#{$prefix}time-picker-roll-cell-selected-bg: var(--#{$prefix}primary-base),
    --#{$prefix}time-picker-roll-cell-selected-hover-color: var(--#{$prefix}primary-contrast),
    --#{$prefix}time-picker-roll-cell-selected-hover-bg: oklch(from var(--#{$prefix}primary-base) calc(l * var(--#{$prefix}theme-hover-lightness)) calc(c * var(--#{$prefix}theme-hover-chroma)) h),
    --#{$prefix}time-picker-inline-select-font-size: var(--#{$prefix}btn-input-sm-font-size),
    --#{$prefix}time-picker-inline-select-color: var(--#{$prefix}btn-input-fg),
    --#{$prefix}time-picker-inline-select-padding-y: var(--#{$prefix}btn-input-sm-padding-y),
    --#{$prefix}time-picker-inline-select-padding-x: var(--#{$prefix}btn-input-sm-padding-x),
    --#{$prefix}time-picker-inline-select-disabled-color: var(--#{$prefix}fg-body),
  ),
  $time-picker-tokens
);
// scss-docs-end time-picker-tokens

// stylelint-enable scss/dollar-variable-default
@layer components {
  .time-picker {
    position: relative;

    &.show {
      @include form-control-group-active();
    }
  }

  .time-picker-popup {
    @include tokens($time-picker-tokens);
  }

  .time-picker-body {
    display: flex;
    align-items: center;
    padding: var(--#{$prefix}time-picker-body-padding);
  }

  .time-picker-inline-select {
    padding: var(--#{$prefix}time-picker-inline-select-padding-y) var(--#{$prefix}time-picker-inline-select-padding-x);
    font-size: var(--#{$prefix}time-picker-inline-select-font-size);
    color: var(--#{$prefix}time-picker-inline-select-color);
    text-align: end;
    appearance: none;
    scrollbar-width: none;
    background-color: transparent;
    border: 0;

    &::-webkit-scrollbar {
      width: 10px;
    }

    // Remove outline from select box in FF
    &:-moz-focusring {
      color: transparent;
      text-shadow: 0 0 0 var(--#{$prefix}time-picker-inline-select-color);
    }

    &:disabled {
      color: var(--#{$prefix}time-picker-inline-select-disabled-color);
    }
  }

  .time-picker-footer {
    display: flex;
    justify-content: flex-end;
    padding: var(--#{$prefix}time-picker-footer-padding);
    border-block-start: var(--#{$prefix}time-picker-footer-border-width) solid var(--#{$prefix}time-picker-footer-border-color);

    .btn + .btn {
      margin-inline-start: .5rem;
    }
  }

  .time-picker-roll {
    padding: 0;
    overflow: hidden;
    @include border-radius(inherit);
  }

  .time-picker-roll-col {
    height: calc(8 * var(--#{$prefix}time-picker-roll-cell-height));
    overflow: scroll;

    scrollbar-width: none;
    scroll-behavior: smooth;

    &::-webkit-scrollbar {
      display: none;
    }

    &:not(:last-child) {
      border-inline-end: var(--#{$prefix}time-picker-roll-col-border-width) solid var(--#{$prefix}time-picker-roll-col-border-color);
    }
  }

  .time-picker-roll-cell {
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--#{$prefix}time-picker-roll-cell-width);
    height: var(--#{$prefix}time-picker-roll-cell-height);
    cursor: pointer;

    &:hover,
    &:focus-visible:not(.selected) {
      color: var(--#{$prefix}time-picker-roll-cell-hover-color);
      background: var(--#{$prefix}time-picker-roll-cell-hover-bg);
    }

    &:focus-visible {
      outline: 0;
    }

    &.selected {
      color: var(--#{$prefix}theme-contrast, var(--#{$prefix}time-picker-roll-cell-selected-color));
      background: var(--#{$prefix}theme-bg, var(--#{$prefix}time-picker-roll-cell-selected-bg));

      &:hover,
      &:focus-visible {
        color: var(--#{$prefix}theme-contrast, var(--#{$prefix}time-picker-roll-cell-selected-hover-color));
        background: var(--#{$prefix}theme-bg, var(--#{$prefix}time-picker-roll-cell-selected-hover-bg));
      }
    }

    &:last-child {
      margin-bottom: calc(7 * var(--#{$prefix}time-picker-roll-cell-height));
    }
  }

}
